package com.nigson.integration.carrier;

import java.time.*;
import com.nigson.integration.providers.CarrierProvider;
import com.nigson.shared.problem.*;
import org.springframework.scheduling.annotation.Scheduled;

/** One bounded booking at a time; durable ACK replay never recreates, reuploads or refetches context. */
public final class CarrierBookingWorker {
 private final CarrierBookingExecution execution;private final CarrierContextClient source;private final CarrierShipmentRequest requests;private final CarrierProvider provider;private final CarrierLabelStorage labels;private final Clock clock;private final Instant approvedUntil;
 public CarrierBookingWorker(CarrierBookingExecution execution,CarrierContextClient source,CarrierShipmentRequest requests,CarrierProvider provider,CarrierLabelStorage labels,Clock clock,Instant approvedUntil){this.execution=java.util.Objects.requireNonNull(execution);this.source=java.util.Objects.requireNonNull(source);this.requests=java.util.Objects.requireNonNull(requests);this.provider=java.util.Objects.requireNonNull(provider);this.labels=java.util.Objects.requireNonNull(labels);this.clock=java.util.Objects.requireNonNull(clock);this.approvedUntil=java.util.Objects.requireNonNull(approvedUntil);}
 @Scheduled(fixedDelayString="${NIGSON_CARRIER_WORKER_DELAY_MS:30000}")public void scheduled(){try{poll();}catch(RuntimeException failure){org.slf4j.LoggerFactory.getLogger(getClass()).warn("CARRIER_DURABLE_RECOVERY_REQUIRED");}}
 public int poll(){var next=execution.claim();if(next.isEmpty())return 0;return process(next.get());}
 public int process(CarrierBookingExecution.Claim claim){CarrierBookingExecution.Claim active=claim;
  try{if(!claim.compatible()){execution.unknown(claim,ProblemCode.PROVIDER_MODE_MISMATCH);return 1;}String stage=claim.checkpoint().path("stage").asString();if(stage.equals("UPLOAD")){var intent=claim.checkpoint().path("labelIntent");var stored=labels.recover(claim.shipmentId(),claim.reference(),intent.path("checksum").asString(),intent.path("bytes").asLong());if(stored==null){if(!claim.checkpoint().has("asyncJobId")){execution.unknown(claim,ProblemCode.PROVIDER_OUTCOME_UNKNOWN);return 1;}var output=provider.confirmed(claim.checkpoint().path("asyncJobId").asString());var regenerated=CarrierLabelCodec.decode(output,claim.checkpoint().path("trackingNumber").asString(),claim.checkpoint().path("packageCount").asInt());if(!regenerated.checksum().equals(intent.path("checksum").asString())||regenerated.bytes().length!=intent.path("bytes").asLong())throw CarrierValues.rule();stored=labels.store(claim.shipmentId(),claim.reference(),regenerated);}var pending=execution.labelStored(claim,stored);if(pending.isEmpty())return 1;active=pending.get();var ack=source.acknowledge(active.shipmentId(),active.checkpoint().path("ack"),active.correlation());execution.acknowledged(active,ack);return 1;}if(stage.equals("ACK")){var ack=source.acknowledge(claim.shipmentId(),claim.checkpoint().path("ack"),claim.correlation());execution.acknowledged(claim,ack);return 1;}
   CarrierBookingExecution.Submission submission;if(claim.mayCreate())submission=execution.submit(claim,source,requests,provider,LocalDate.ofInstant(clock.instant(),ZoneId.of("Africa/Lagos")),approvedUntil);else if((stage.equals("ASYNC")||stage.equals("LABEL_PENDING"))&&claim.checkpoint().has("asyncJobId"))submission=execution.retrieve(claim,provider);else{provider.trackReference(claim.reference().toString(),LocalDate.now(clock).minusDays(90),LocalDate.now(clock));execution.unknown(claim,ProblemCode.PROVIDER_OUTCOME_UNKNOWN);return 1;}
   if(!submission.persisted()||submission.claim()==null)return 1;active=submission.claim();var label=CarrierLabelCodec.decode(submission.output(),active.checkpoint().path("trackingNumber").asString(),active.checkpoint().path("packageCount").asInt());var planned=execution.labelIntent(active,labels.key(active.shipmentId()),label.checksum(),label.bytes().length);if(planned.isEmpty())return 1;active=planned.get();var stored=labels.store(active.shipmentId(),active.reference(),label);var pending=execution.labelStored(active,stored);if(pending.isEmpty())return 1;active=pending.get();var ack=source.acknowledge(active.shipmentId(),active.checkpoint().path("ack"),active.correlation());execution.acknowledged(active,ack);return 1;
  }catch(RuntimeException failure){try{execution.unknown(active,failure instanceof Problem.Failure problem&&problem.code==ProblemCode.PROVIDER_MODE_MISMATCH?ProblemCode.PROVIDER_MODE_MISMATCH:ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}catch(RuntimeException durable){org.slf4j.LoggerFactory.getLogger(getClass()).warn("CARRIER_DURABLE_LEASE_RECOVERY_REQUIRED");}return 1;}
 }
}
